-- Canonical star schema for the Danish health-care footprint, reference year 2022.
-- Generated by analysis.build_star_schema; this DDL is the contract the CSVs satisfy.
-- Types are PostgreSQL; they adapt unchanged to DuckDB, and with minor edits to
-- Fabric/Snowflake.
--
-- Load order matters: dimensions first, then facts, or the foreign keys fail.

-- ============================================================ DIMENSIONS

CREATE TABLE dim_model (
    model_id                 INTEGER      PRIMARY KEY,
    model_label              VARCHAR(300) NOT NULL,
    background_year          VARCHAR(30)  NOT NULL,
    analysis_year            INTEGER      NOT NULL,
    mrio                     VARCHAR(100) NOT NULL,
    danish_block_correction  VARCHAR(200),
    gwp_vintage              VARCHAR(30)  NOT NULL,
    scope_boundary           VARCHAR(60)  NOT NULL,
    capital                  VARCHAR(60)  NOT NULL
);

CREATE TABLE dim_region (
    region_id      INTEGER      PRIMARY KEY,
    region_code    VARCHAR(40)  NOT NULL UNIQUE,  -- ISO3, or the region name where no ISO3 exists
    region_name    VARCHAR(200) NOT NULL,
    world_region   VARCHAR(60)  NOT NULL,
    is_row_region  BOOLEAN      NOT NULL,
    is_domestic    BOOLEAN      NOT NULL
);

CREATE TABLE dim_industry_group (
    industry_group_id   INTEGER      PRIMARY KEY,
    industry_group_name VARCHAR(120) NOT NULL UNIQUE
);

CREATE TABLE dim_industry (
    industry_id       INTEGER      PRIMARY KEY,
    industry_code     VARCHAR(40)  NOT NULL UNIQUE,  -- EXIOBASE code, no A_ / C_ prefix
    industry_name     VARCHAR(300) NOT NULL,
    industry_group_id INTEGER      NOT NULL REFERENCES dim_industry_group (industry_group_id),
    industry_type     VARCHAR(30)  NOT NULL          -- 'MRIO industry' | 'bottom-up item'
);

CREATE TABLE dim_indicator (
    indicator_id   INTEGER      PRIMARY KEY,
    indicator_code VARCHAR(80)  NOT NULL UNIQUE,
    unit           VARCHAR(40)  NOT NULL
);

CREATE TABLE dim_scope (
    scope_id   INTEGER     PRIMARY KEY,
    scope_name VARCHAR(40) NOT NULL UNIQUE
);

CREATE TABLE dim_demand_component (
    demand_component_id   INTEGER     PRIMARY KEY,
    demand_component_name VARCHAR(80) NOT NULL UNIQUE
);

CREATE TABLE dim_health_function (
    health_function_id   INTEGER      PRIMARY KEY,
    health_function_name VARCHAR(120) NOT NULL UNIQUE
);

-- ================================================================= FACTS

-- Grain: model x indicator x demand component x producing region x producing industry.
CREATE TABLE fact_footprint_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, demand_component_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x indicator x demand component x purchased region x purchased industry.
-- NOT interchangeable with fact_footprint_node: that one says where pressure ARISES,
-- this one says which purchase DRIVES it. They are marginals of the same table and
-- must never be summed together.
CREATE TABLE fact_footprint_product (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    demand_component_id   INTEGER NOT NULL REFERENCES dim_demand_component (demand_component_id),
    purchased_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    purchased_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, demand_component_id,
                 purchased_region_id, purchased_industry_id)
);

-- Grain: model x indicator x scope x producing region x producing industry.
CREATE TABLE fact_scope_node (
    model_id              INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id          INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    scope_id              INTEGER NOT NULL REFERENCES dim_scope (scope_id),
    producing_region_id   INTEGER NOT NULL REFERENCES dim_region (region_id),
    producing_industry_id INTEGER NOT NULL REFERENCES dim_industry (industry_id),
    value                 DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (model_id, indicator_id, scope_id,
                 producing_region_id, producing_industry_id)
);

-- Grain: model x indicator. Carried with every result set so a health share of the
-- national footprint can always be formed without leaving the model.
CREATE TABLE fact_national_total (
    model_id                   INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id               INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    national_footprint         DOUBLE PRECISION NOT NULL,
    national_supply_chain      DOUBLE PRECISION,
    national_direct_households DOUBLE PRECISION,
    healthcare_footprint_mrio  DOUBLE PRECISION,
    healthcare_share_pct       DOUBLE PRECISION,
    PRIMARY KEY (model_id, indicator_id)
);

-- Grain: model x indicator x health function (SHA).
CREATE TABLE fact_health_function (
    model_id           INTEGER NOT NULL REFERENCES dim_model (model_id),
    indicator_id       INTEGER NOT NULL REFERENCES dim_indicator (indicator_id),
    health_function_id INTEGER NOT NULL REFERENCES dim_health_function (health_function_id),
    value              DOUBLE PRECISION NOT NULL,
    expenditure_meur   DOUBLE PRECISION,
    intensity_per_meur DOUBLE PRECISION,
    PRIMARY KEY (model_id, indicator_id, health_function_id)
);
